## Problem

When uploading a large body, the server can close the connection before
the client finishes writing. Node.js emits an `error` event on the socket
with code `EPIPE`. Since Axios had no `error` listener on the socket, this
became an `uncaughtException` and crashed the process on Linux/macOS.

Fixes #10558 

## Root cause

In `lib/adapters/http.js`, the `handleRequestSocket` callback set up
keep-alive but never attached a socket-level error handler.

## Solution

Attach a single `error` listener per socket using a Symbol guard to avoid
leaking listeners on keep-alive connections that are reused across requests.

The error is forwarded via `req.destroy(err)`, which triggers the existing
`handleRequestError` handler, so the promise rejects cleanly instead of
crashing the process.

## Testing

- Verified crash on Linux (Node.js v24, via Docker)
- Verified clean rejection after fix on Linux
- Verified listener presence on Windows via manual EPIPE emission

## Notes

- The `fetch` adapter is not affected (handled internally by the Fetch API)
- Windows does not exhibit the crash due to `socketErrorListener` in
  Node's `_http_client`, but the fix is still necessary for Linux/macOS
  production environments
  
  ## Before
  
<img width="462" height="144" alt="image" src="https://github.com/user-attachments/assets/2664b86b-035e-4b38-98fe-7c01cb4f9dde" />

## After
  
<img width="517" height="165" alt="image" src="https://github.com/user-attachments/assets/823b6d73-a079-42d0-a7a5-9682c1dea19a" />

I've used this .js script to test the issue in windows environment:

```
const http = require("node:http");
const axios = require("axios");

const server = http.createServer((req, res) => {
  req.on("error", () => {});
  res.on("error", () => {});
  setTimeout(() => {
    res.end();
    res.socket.destroy();
  }, 50);
});

async function main() {
  await new Promise((resolve) => server.listen(resolve));
  const endpoint = "http://127.0.0.1:" + server.address().port;
  console.log("Server listening:", endpoint);

  const bigBody = Buffer.alloc(10 * 1024 * 1024, "a");

  const axiosInstance = axios.create();

  axiosInstance.interceptors.request.use((config) => {
    config.transport = {
      request: (options, callback) => {
        const req = http.request(options, callback);

        req.on("socket", (socket) => {
          socket.once("connect", () => {
            setTimeout(() => {
              console.log("\n--- Manually emitting EPIPE on socket ---");

              const errorListeners = socket.listeners("error");
              console.log(
                `Socket has ${errorListeners.length} error listener(s):`,
                errorListeners.map((fn) => fn.name)
              );

              if (errorListeners.length === 0) {
                console.log(
                  "NO error listener found — this would crash the process on Linux!"
                );
              } else {
                console.log(
                  "Error listener found — fix is working correctly."
                );
              }

              socket.emit("error", Object.assign(new Error("write EPIPE"), {
                errno: -32,
                code: "EPIPE",
                syscall: "write",
              }));
            }, 10);
          });
        });

        return req;
      },
    };
    return config;
  });

  try {
    await axiosInstance.post(endpoint, bigBody);
  } catch (e) {
    console.log("\nResult:", e.message);
    console.log("isAxiosError:", e.isAxiosError);
  }

  server.close();
}

main().catch((e) => {
  console.error("Unhandled crash — fix is NOT working:", e.message);
  process.exit(1);
});
```


